WITH metrics AS (SELECT *, AVG(cost) OVER (PARTITION BY status, carrier ORDER BY cost, id ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING) AS cost_avg_6_prior, NTILE(10) OVER w_recent AS cost_bucket, RANK() OVER w_grp AS cost_rank, ROW_NUMBER() OVER (PARTITION BY status, order_id ORDER BY delivered_date, id) AS row_seq, MAX(cost) OVER w_grp_2 AS carrier_max_cost FROM shipments WINDOW w_recent AS (PARTITION BY carrier ORDER BY cost DESC, id), w_grp AS (ORDER BY cost), w_grp_2 AS (PARTITION BY carrier)) SELECT CASE WHEN carrier_max_cost >= 106 THEN 'HIGH' ELSE 'LOW' END AS carrier_max_cost_tier, DATE_TRUNC('WEEK', delivered_date) AS week_start, SIZE(COLLECT_SET(carrier)) AS num_carriers, COUNT(DISTINCT order_id) AS distinct_order_ids, SIZE(COLLECT_SET(status)) AS num_status, ROUND(AVG(cost_bucket), 2) AS avg_cost_bucket FROM metrics GROUP BY ROLLUP (CASE WHEN carrier_max_cost >= 106 THEN 'HIGH' ELSE 'LOW' END, DATE_TRUNC('WEEK', delivered_date)) ORDER BY num_carriers DESC NULLS LAST;
